    else:
        return send_file(os.path.join(app.cwd, path))

async def process_events(self, events: list[Event], batch: bool) -> None:
    awake_events: list[Event] = []
    try:
        for event in events:
            if not event.data:
                self.awaiting_data_events[event._id] = event
                client_awake = await event.get_data()
                del self.awaiting_data_events[event._id]
                if not client_awake:
                    await self.clean_event(event)
                    continue
            event.send_message("process_starts")
            awake_events.append(event)
        if not awake_events:
            return
        begin_time = time.time()
        try:
            response = await self.call_prediction(awake_events, batch)
            err = None
        except Exception as e:
            traceback.print_exc()
            response = None
            err = e
            for event in awake_events:
                event.send_message(
                    "process_completed",
                    {
                        "output": {
                            "error": None
                            if len(e.args) and e.args[0] is None
                            else str(e)
                        },
                        "success": False,
                    },
                    final=True,
                )
        if response and response.get("is_generating", False):
            old_response = response
            old_err = err
            while response and response.get("is_generating", False):
                old_response = response
                old_err = err
                for event in awake_events:
                    event.send_message(
                        "process_generating",
                        {
                            "output": old_response,

def main(request: fastapi.Request, user: str = Depends(get_current_user)):
    mimetypes.add_type("application/javascript", ".js")
    blocks = app.get_blocks()
    root_path = (
        request.scope.get("root_path")
        or request.headers.get("X-Direct-Url")
        or ""
    )
    if app.auth is None or user is not None:
        config = app.get_blocks().config
        config["root"] = route_utils.strip_url(root_path)
    else:
        config = {
            "auth_required": True,
            "auth_message": blocks.auth_message,
            "space_id": app.get_blocks().space_id,
            "root": route_utils.strip_url(root_path),
        }

    try:
        template = (
            "frontend/share.html" if blocks.share else "frontend/index.html"
        )
        return templates.TemplateResponse(
            template,
            {"request": request, "config": config},
        )
    except TemplateNotFound as err:
        if blocks.share:
            raise ValueError(
                "Did you install Gradio from source files? Share mode only "
                "works when Gradio is installed through the pip package."
            ) from err
        else:
            raise ValueError(
                "Did you install Gradio from source files? You need to build "
                "the frontend by running /scripts/build_frontend.sh"
            ) from err

def save(self):
    self['__meta__'] = {
        'httpie': __version__
    }
    if self.helpurl:
        self['__meta__']['help'] = self.helpurl

    if self.about:
        self['__meta__']['about'] = self.about

    self.ensure_directory()

    json_string = json.dumps(
        obj=self,
        indent=4,
        sort_keys=True,
        ensure_ascii=True,
    )
    self.path.write_text(json_string + '\n', encoding=UTF8)

def cookies(self, jar: RequestsCookieJar):
    # <https://docs.python.org/3/library/cookielib.html#cookie-objects>
    stored_attrs = ['value', 'path', 'secure', 'expires']
    self['cookies'] = {}
    for cookie in jar:
        self['cookies'][cookie.name] = {
            attname: getattr(cookie, attname)
            for attname in stored_attrs
        }

