def open_soap_envelope(text):
    """

    :param text: SOAP message
    :return: dictionary with two keys "body"/"header"
    """
    try:
        envelope = ElementTree.fromstring(text)
    except Exception as exc:
        raise XmlParseError("%s" % exc)

    assert envelope.tag == '{%s}Envelope' % soapenv.NAMESPACE
    assert len(envelope) >= 1
    content = {"header": [], "body": None}

    for part in envelope:
        if part.tag == '{%s}Body' % soapenv.NAMESPACE:
            assert len(part) == 1
            content["body"] = ElementTree.tostring(part[0], encoding="UTF-8")
        elif part.tag == "{%s}Header" % soapenv.NAMESPACE:
            for item in part:
                _str = ElementTree.tostring(item, encoding="UTF-8")
                content["header"].append(_str)

    return content

def analyze(self, avc):
    import commands
    if avc.has_any_access_in(['execmod']):
        # MATCH
        if (commands.getstatusoutput("eu-readelf -d %s | fgrep -q TEXTREL" % avc.tpath)[0] == 1):
            return self.report(("unsafe"))

        mcon = selinux.matchpathcon(avc.tpath.strip('"'), S_IFREG)[1]
        if mcon.split(":")[2] == "lib_t":
            return self.report()
    return None

def generate_unauthed_file_access_url(path_id: str) -> str:
    signed_data = TimestampSigner(salt=LOCAL_FILE_ACCESS_TOKEN_SALT).sign(path_id)
    token = base64.b16encode(signed_data.encode()).decode()

    filename = path_id.split("/")[-1]
    return reverse("local_file_unauthed", args=[token, filename])

def serve_file(
    request: HttpRequest,
    maybe_user_profile: Union[UserProfile, AnonymousUser],
    realm_id_str: str,
    filename: str,
    url_only: bool = False,
    download: bool = False,
) -> HttpResponseBase:
    path_id = f"{realm_id_str}/{filename}"
    realm = get_valid_realm_from_request(request)
    is_authorized = validate_attachment_request(maybe_user_profile, path_id, realm)

    if is_authorized is None:
        return HttpResponseNotFound(_("<p>File not found.</p>"))
    if not is_authorized:
        return HttpResponseForbidden(_("<p>You are not authorized to view this file.</p>"))
    if url_only:
        url = generate_unauthed_file_access_url(path_id)
        return json_success(request, data=dict(url=url))

    mimetype, encoding = guess_type(path_id)
    download = download or mimetype not in INLINE_MIME_TYPES

    if settings.LOCAL_UPLOADS_DIR is not None:
        return serve_local(request, path_id, download=download)
    else:
        return serve_s3(request, path_id, download=download)

def test_visitor(self):
    class CustomVisitor(self.asdl.VisitorBase):
        def __init__(self):
            super().__init__()
            self.names_with_seq = []

        def visitModule(self, mod):
            for dfn in mod.dfns:
                self.visit(dfn)

        def visitType(self, type):
            self.visit(type.value)

        def visitSum(self, sum):
            for t in sum.types:
                self.visit(t)

        def visitConstructor(self, cons):
            for f in cons.fields:
                if f.seq:
                    self.names_with_seq.append(cons.name)

    v = CustomVisitor()
    v.visit(self.types['mod'])
    self.assertEqual(v.names_with_seq, ['Module', 'Interactive', 'Suite'])

