    auth = auths and sorted(auths)[0][1] or None
    if auth:
        auth.request(method, request_uri, headers, body)

    (response, content) = self._conn_request(
        conn, request_uri, method, body, headers
    )

    if auth:
        if auth.response(response, body):
            auth.request(method, request_uri, headers, body)
