def process_request(self, request, spider):
    if 'splash' not in request.meta:
        return

    if request.method not in {'GET', 'POST'}:
        logger.warning(
            "Currently only GET and POST requests are supported by "
            "SplashMiddleware; %(request)s will be handled without Splash",
            {'request': request},
            extra={'spider': spider}
        )
        return request

    if request.meta.get("_splash_processed"):
        # don't process the same request more than once
        return

    splash_options = request.meta['splash']
    request.meta['_splash_processed'] = True

    slot_policy = splash_options.get('slot_policy', self.slot_policy)
    self._set_download_slot(request, request.meta, slot_policy)

    args = splash_options.setdefault('args', {})

    if '_replaced_args' in splash_options:
        # restore arguments before sending request to the downloader
        load_args = {}
        save_args = []
        local_arg_fingerprints = {}
        for name in splash_options['_replaced_args']:
            fp = args[name]
            # Use remote Splash argument cache: if Splash key
            # for a value is known then don't send the value to Splash;
            # if it is unknown then try to save the value on server using
            # ``save_args``.
            if fp in self._remote_keys:
                load_args[name] = self._remote_keys[fp]
                del args[name]
            else:
                save_args.append(name)
                args[name] = self._argument_values[fp]

            local_arg_fingerprints[name] = fp

        if load_args:
            args['load_args'] = load_args
        if save_args:
            args['save_args'] = save_args
        splash_options['_local_arg_fingerprints'] = local_arg_fingerprints

        del sp

def ls(self, value=None) -> list[dict[str, str]] | None:
    """
    Parameters:
        value: file path as a list of strings for each directory level relative to the root.
    Returns:
        tuple of list of files in directory, then list of folders in directory
    """

    def expand_braces(text, seen=None):
        if seen is None:
            seen = set()

        spans = [m.span() for m in re.finditer("{[^{}]*}", text)][::-1]
        alts = [text[start + 1 : stop - 1].split(",") for start, stop in spans]

        if len(spans) == 0:
            if text not in seen:
                yield text
            seen.add(text)

        else:
            for combo in itertools.product(*alts):
                replaced = list(text)
                for (start, stop), replacement in zip(spans, combo):
                    replaced[start:stop] = replacement

                yield from expand_braces("".join(replaced), seen)

    def make_tree(files):
        tree = []
        for file in files:
            parts = file.split(os.path.sep)
            make_node(parts, tree)
        return tree

    def make_node(parts, tree):
        _tree = tree
        for i in range(len(parts)):
            if _tree is None:
                continue
            if i == len(parts) - 1:
                type = "file"
                _tree.append({"path": parts[i], "type": type, "children": None})
                continue
            type = "folder"
            j = next(
                (index for (index, v) in enumerate(_tree) if v["path"] == parts[i]),
                None,
            )
            if j is not None:
                _tree = _tree[j]["children"]
            else:
                _tree.append({"path": parts[i], "type": type, "children": []})
                _tree = _tree[-1]["children"]

